96	uint64_t ModuleSummaryIndex::getFlags() const {
97	  uint64_t Flags = 0;
98	  // Flags & 0x4 is reserved. DO NOT REUSE.
99	  if (withGlobalValueDeadStripping())
100	    Flags |= 0x1;
101	  if (skipModuleByDistributedBackend())
102	    Flags |= 0x2;
103	  if (enableSplitLTOUnit())
104	    Flags |= 0x8;
105	  if (partiallySplitLTOUnits())
106	    Flags |= 0x10;
107	  if (withAttributePropagation())
108	    Flags |= 0x20;
109	  if (withDSOLocalPropagation())
110	    Flags |= 0x40;
111	  if (withWholeProgramVisibility())
112	    Flags |= 0x80;
113	  if (withSupportsHotColdNew())
114	    Flags |= 0x100;
115	  if (hasUnifiedLTO())
116	    Flags |= 0x200;
117	  if (withInternalizeAndPromote())
118	    Flags |= 0x400;
119	  return Flags;
120	}
