448	void Attributes::add(const Twine &Name, const Twine &Value,
449	                     const Twine &Comment) {
450	  std::string A = Name.str();
451	  A += "=\"";
452	  A += Value.str();
453	  A += "\"";
454	  Attrs.push_back(A);
455	  addComment(Comment);
456	}
457	
458	void Attributes::addComment(const Twine &Comment) {
459	  if (!Comment.isTriviallyEmpty()) {
460	    if (Comments.empty())
461	      Comments = " // ";
462	    else
463	      Comments += ", ";
464	    Comments += Comment.str();
465	  }
466	}
467	
468	std::string Attributes::getAsString() const {
469	  if (Attrs.empty())
470	    return "";
471	
472	  std::string Ret = "[";
473	  for (auto &A : Attrs)
474	    Ret += A + ",";
475	  Ret.pop_back();
476	  Ret += "];";
477	  Ret += Comments;
478	  return Ret;
479	}
