481	static std::string linkageToString(GlobalValue::LinkageTypes LT) {
482	  switch (LT) {
483	  case GlobalValue::ExternalLinkage:
484	    return "extern";
485	  case GlobalValue::AvailableExternallyLinkage:
486	    return "av_ext";
487	  case GlobalValue::LinkOnceAnyLinkage:
488	    return "linkonce";
489	  case GlobalValue::LinkOnceODRLinkage:
490	    return "linkonce_odr";
491	  case GlobalValue::WeakAnyLinkage:
492	    return "weak";
493	  case GlobalValue::WeakODRLinkage:
494	    return "weak_odr";
495	  case GlobalValue::AppendingLinkage:
496	    return "appending";
497	  case GlobalValue::InternalLinkage:
498	    return "internal";
499	  case GlobalValue::PrivateLinkage:
500	    return "private";
501	  case GlobalValue::ExternalWeakLinkage:
502	    return "extern_weak";
503	  case GlobalValue::CommonLinkage:
504	    return "common";
505	  }
506	
507	  return "<unknown>";
508	}
