101	  case CalleeInfo::HotnessType::Unknown:
102	    return "unknown";
103	  case CalleeInfo::HotnessType::Cold:
104	    return "cold";
105	  case CalleeInfo::HotnessType::None:
106	    return "none";
107	  case CalleeInfo::HotnessType::Hot:
108	    return "hot";
109	  case CalleeInfo::HotnessType::Critical:
110	    return "critical";
111	  }
112	  llvm_unreachable("invalid hotness");
113	}
